// 关联成员行时**不**按 status 过滤，这样「申请中」（pending）也能被看到，
// 前台才能把按钮从「申请加入」换成「申请中，等待确认」。
// 但可见性与 joined 仍然只认 active：待审的人不该看到仅成员项目的内容。
//
// joined 必须套 COALESCE。这是 LEFT JOIN：匿名访客与未加入的用户没有成员行，
// m.status 是 NULL，而 SQL 三值逻辑下 `NULL = 'active'` 的结果是 **NULL 而不是 false**。
// 直接写 `(m.status = 'active')::boolean` 会让这一列返回 NULL，Go 侧按 bool 扫描时
// 报 `cannot scan NULL into *bool`，整个项目详情接口 500。
// 隔壁 ListVisibleFbProjects 用的是 `IS NOT NULL`，那种写法天然不会是 NULL。
func (q *Queries) GetVisibleFbProject(ctx context.Context, arg GetVisibleFbProjectParams) (GetVisibleFbProjectRow, error) {
	row := q.db.QueryRow(ctx, getVisibleFbProject, arg.ViewerID, arg.Slug)
	var i GetVisibleFbProjectRow
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.KeyPrefix,
		&i.Name,
		&i.Summary,
		&i.Description,
		&i.Cover,
		&i.TryUrl,
		&i.Status,
		&i.Visibility,
		&i.JoinMode,
		&i.NextNumber,
		&i.Sort,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Joined,
		&i.MemberRole,
		&i.MemberStatus,
		&i.MemberCount,
		&i.FeedbackCount,
	)
	return i, err
}

