const upsertFbMember = `-- name: UpsertFbMember :one

INSERT INTO fb_project_member (project_id, user_id, role, status)
VALUES ($1, $2, $3, $4)
ON CONFLICT (project_id, user_id) DO UPDATE
SET role = EXCLUDED.role, status = EXCLUDED.status
RETURNING project_id, user_id, role, status, joined_at
`

type UpsertFbMemberParams struct {
	ProjectID int64
	UserID    int64
	Role      string
	Status    string
}

// ---------- 成员 ----------
func (q *Queries) UpsertFbMember(ctx context.Context, arg UpsertFbMemberParams) (FbProjectMember, error) {
	row := q.db.QueryRow(ctx, upsertFbMember,
		arg.ProjectID,
		arg.UserID,
		arg.Role,
		arg.Status,
	)
	var i FbProjectMember
	err := row.Scan(
		&i.ProjectID,
		&i.UserID,
		&i.Role,
		&i.Status,
		&i.JoinedAt,
	)
	return i, err
}
